const base = $('Prepare Claude Request').first().json;
const cur = $input.item.json;
let reason = 'unknown failure';
if (cur.parse_error) { reason = 'invalid JSON after retry: ' + cur.parse_error; }
else if (cur.error) { reason = 'Claude API error: ' + (typeof cur.error === 'string' ? cur.error : (cur.error.message || 'request failed')); }
